function validate([stones]) {
  if (!Array.isArray(stones) || stones.length < 2 || stones.length > 100000) return 'stones needs 2 to 100000 positions.';
  if (stones[0] !== 0) return 'The first stone must be at position 0.';
  for (let i = 0; i < stones.length; i++) {
    if (!Number.isInteger(stones[i]) || stones[i] < 0 || stones[i] > 1e9) return 'Each position is a whole number from 0 to 10^9.';
    if (i > 0 && stones[i] <= stones[i - 1]) return 'Positions must be strictly increasing.';
  }
  return null;
}

