function maxJump(stones) {
  const n = stones.length;
  let best = stones[1] - stones[0];
  for (let i = 2; i < n; i++) {
    const skip = stones[i] - stones[i - 2];
    if (skip > best) {
      best = skip;
    }
  }
  return best;
}

