function maxJump(stones) {
  // Try every way to send each middle stone on the way out, on the way back, or nowhere.
  const n = stones.length;
  const middle = n - 2;
  const longestGap = path => {
    let longest = 0;
    for (let k = 1; k < path.length; k++) longest = Math.max(longest, path[k] - path[k - 1]);
    return longest;
  };
  let answer = Infinity;
  for (let code = 0; code < 3 ** middle; code++) {
    const out = [stones[0]], back = [stones[0]];
    let rest = code;
    for (let j = 1; j <= middle; j++) {
      if (rest % 3 === 1) out.push(stones[j]);
      else if (rest % 3 === 2) back.push(stones[j]);
      rest = Math.floor(rest / 3);
    }
    out.push(stones[n - 1]);
    back.push(stones[n - 1]);
    answer = Math.min(answer, Math.max(longestGap(out), longestGap(back)));
  }
  return answer;
}

