function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const maxGap = rand() < 0.5 ? 500000 : 1 + Math.floor(rand() * 1000);
    const stones = [0];
    for (let i = 1; i < n; i++) stones.push(stones[i - 1] + 1 + Math.floor(rand() * maxGap));
    return [stones];
  }
  const n = 2 + Math.floor(rand() * 8);
  const maxGap = rand() < 0.2 ? 100000000 : 1 + Math.floor(rand() * 10);
  const stones = [0];
  for (let i = 1; i < n; i++) stones.push(stones[i - 1] + 1 + Math.floor(rand() * maxGap));
  return [stones];
}
